 // Times are recorded times, not proof of the moment food was eaten or activity began.
 function eventMs(r){const d=dayOf(r),t=String(r.time||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(t))return null;const n=new Date(d+'T'+t+':00Z').getTime();return Number.isFinite(n)?n:null;}
 function buildTimeline(rows){const out=[];for(const r of rows){const at=eventMs(r);if(at===null)continue;const base={at,date:dayOf(r),time:r.time};const diets=Array.isArray(r.diets)?r.diets:[];if(diets.length){const snaps=Array.isArray(r.nutritionSnapshots)?r.nutritionSnapshots:[];const isWater=diets.every(x=>isWaterDesc(x,snaps));let carb=0,known=true;for(const desc of diets){const name=String(desc).replace(/\s*\([\d.,]+\s+[^()]+\)\s*$/,'');const sn=snaps.find(x=>x?.name===name);if(isWaterDesc(desc,snaps))continue;if(!sn||!finite(sn.amount)||!validBasis(sn)||!finite(sn.nutrients?.carbohydrate)){known=false;continue}carb+=Number(sn.nutrients.carbohydrate)*Number(sn.amount)/Number(sn.basis)}if(!isWater)out.push({...base,kind:'meal',label:diets.filter(x=>!isWaterDesc(x,snaps)).join(', '),carb:known?carb:null});for(const water of diets.filter(x=>isWaterDesc(x,snaps))){const m=String(water).match(/\(([\d.,]+)\s+([^()]+)\)\s*$/);let ml=null;if(m){const amount=Number(m[1].replace(',','.')),u=m[2].trim().toLocaleLowerCase('tr');if(Number.isFinite(amount)&&amount>0){if(u==='ml')ml=amount;else if(['bardak','glass'].includes(u))ml=amount*250}}out.push({...base,kind:'water',label:String(water),value:ml})}}if(!['pressure','activity','nutrition_only','symptom_only','medication_only'].includes(r.type)){const v=num(r.val??r.glucoseVal);if(v>0)out.push({...base,kind:'glucose',value:v,category:r.category||'',label:`${v} mg/dL · ${{fasting:'Açlık',pre_meal:'Yemek öncesi',post_meal:'Yemek sonrası',control:'Kontrol'}[r.category]||'Tür belirtilmemiş'}`})}if(r.type==='pressure'){const sys=num(r.sys??r.bpSys),dia=num(r.dia??r.bpDia);if(sys>0&&dia>0)out.push({...base,kind:'pressure',value:sys,second:dia,pulse:num(r.pulse??r.bpPulse),label:`${sys}/${dia} mmHg`})}if(r.type==='activity'){const v=num(r.duration??r.actDuration);if(v>0)out.push({...base,kind:'activity',value:v,label:`${r.name||r.actName||'Aktivite'} · ${v} dk`})}if(r.drugs)out.push({...base,kind:'medicine',label:String(r.drugs)});if(Array.isArray(r.symptoms)&&r.symptoms.length)out.push({...base,kind:'symptom',label:r.symptoms.join(', ')})}return out.sort((a,b)=>a.at-b.at);}
