  if(!metrics.length)metrics.push(metric('Kan şekeri','mg/dL',()=>null));
  metrics.push(metric('Büyük tansiyon','mmHg',d=>avg(d.bloodPressure.map(x=>x.sys))),metric('Küçük tansiyon','mmHg',d=>avg(d.bloodPressure.map(x=>x.dia))),metric('Su','ml/gün',water),metric('Kalori','kcal/gün',d=>d.meals>0&&d.caloriesKnown===d.foodCount?d.calories:null),metric('Karbonhidrat','g/gün',d=>d.meals>0&&d.known.carbohydrate===d.foodCount?d.totals.carbohydrate:null),metric('Protein','g/gün',d=>d.meals>0&&d.known.protein===d.foodCount?d.totals.protein:null),metric('Yağ','g/gün',d=>d.meals>0&&d.known.fat===d.foodCount?d.totals.fat:null),metric('Aktivite','dk/gün',d=>d.activityCount>0?d.activityMinutes:null));
