 function setup(){const d=document.getElementById('healthReportDialog');if(!d)return;const start=document.getElementById('healthReportStart'),end=document.getElementById('healthReportEnd');const today=new Date();const first=new Date(today.getFullYear(),today.getMonth(),today.getDate()-29);start.value=localISO(first);end.value=localISO(today);document.getElementById('healthReportCancel').onclick=()=>d.close();document.getElementById('healthReportForm').addEventListener('submit',e=>{e.preventDefault();const startValue=start.value,endValue=end.value,error=document.getElementById('healthReportError');if(!startValue||!endValue||startValue>endValue){error.textContent='Geçerli bir tarih aralığı seçin.';error.hidden=false;return;}error.hidden=true;const a=analyze(DataManager.getAll(),startValue,endValue);const note=document.getElementById('healthReportNote').value.trim();const profile=DataManager.getProfile()||{},isEnglish=window.GLKOAITestLanguage?.currentLang==='en';const text=d.dataset.mode==='alternative'?window.AlternativeReport.report(profile,a,startValue,endValue,note):d.dataset.mode==='graph'?comparisonReport(profile,a,startValue,endValue,note,isEnglish):report(profile,a,startValue,endValue,note,isEnglish);if(d.dataset.mode==='pdf'||d.dataset.mode==='graph'){const w=window.open('','_blank');if(!w){error.textContent='Rapor penceresi açılamadı. Açılır pencerelere izin verin.';error.hidden=false;return;}let printed=false;const print=()=>{if(!printed&&d.dataset.mode==='pdf'){printed=true;if(typeof w.printReport==='function')w.printReport('short');else w.print();}};w.addEventListener('load',print,{once:true});w.document.open();w.document.write(text);w.document.close();if(d.dataset.mode==='pdf')setTimeout(print,500);}else{const url=URL.createObjectURL(new Blob([text],{type:'text/html;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`${d.dataset.mode==='alternative'?'GLKAI_Alternatif_Rapor':'GLKAI_Doktor_Raporu'}_${startValue}_${endValue}.html`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}d.close();});}
 function open(mode){const d=document.getElementById('healthReportDialog');d.dataset.mode=mode;document.getElementById('healthReportTitle').textContent=mode==='pdf'?'PDF RAPOR OLUŞTUR':mode==='graph'?'KARŞILAŞTIRMA GRAFİĞİ':mode==='alternative'?'HTML RAPOR OLUŞTUR':'HTML RAPOR OLUŞTUR';document.getElementById('healthReportSubmit').textContent=mode==='pdf'?'PDF İÇİN YAZDIR':mode==='graph'?'GRAFİĞİ AÇ':mode==='alternative'?'HTML RAPORU İNDİR':'HTML RAPORU İNDİR';document.getElementById('healthReportError').hidden=true;if(!d.open)d.showModal();}
